import { Mesh, PlaneGeometry, MeshBasicNodeMaterial, SRGBColorSpace, DoubleSide } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const tex = ctx.textureLoader(config.imageUrl);
  if (tex) {
    tex.colorSpace = SRGBColorSpace;
    if (tex.generateMipmaps !== undefined) {
      tex.generateMipmaps = true;
    }
  }

  // Atlas region: (x, y, w, h) = (0, 0, 512, 320)
  const regionX = 0;
  const regionY = 0;
  const regionW = 512;
  const regionH = 320;

  // Derive atlas dimensions from the loaded image (fallback to region bounds).
  const img = tex && tex.image;
  const atlasW = (img && img.width) ? img.width : regionW;
  const atlasH = (img && img.height) ? img.height : regionH;

  // UV remap: pixel-space region -> normalized UV with Y-flip for texture convention.
  const uScale = regionW / atlasW;
  const vScale = regionH / atlasH;
  const uOffset = regionX / atlasW;
  const vOffset = 1 - (regionY + regionH) / atlasH;

  // Plane sized to the region's aspect ratio (1.6 : 1) in scene units.
  const aspect = regionW / regionH;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // TSL node graph: sample the atlas texture at the remapped UV coordinates.
  const remappedUv = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));
  const mapNode = texture(tex, remappedUv);

  const material = new MeshBasicNodeMaterial();
  material.colorNode = mapNode;
  material.transparent = true;
  material.side = DoubleSide;
  material.depthWrite = false;

  const mesh = new Mesh(geometry, material);
  // Sprite placement: plane faces +Z, camera at +Z, so it billboards naturally.
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.renderOrder = 1;
  mesh.frustumCulled = false;

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
